'use client';
import {useEffect,useRef,useState} from 'react';
import {routeUrl} from '@/lib/idol/journey';
import {safeArtistReturn} from '@/lib/idol/artist-navigation';
import {stageSourceKey,stageHasValidBinding} from '@/lib/idol/stage-source';
import type {createCherrybulletReview,ReadOnlyImageResolver} from '@/lib/idol/design-review/cw-runtime/cherrybullet-host.mjs';
const production={routeUrl,safeArtistReturn,stageSourceKey,stageHasValidBinding};

/** Real main-site review boundary. No private catalog fetch, saving or storage API. */
export default function CherrybulletReview({resolveImage=null,catalog=null}:{resolveImage?:ReadOnlyImageResolver|null;catalog?:unknown}){
  const host=useRef<HTMLDivElement>(null);
  const [attempt,setAttempt]=useState(0),[message,setMessage]=useState('正在载入 Cherry Bullet…'),[failed,setFailed]=useState(false);
  useEffect(()=>{
    const controller=new AbortController();let mounted:ReturnType<typeof createCherrybulletReview>|null=null;
    void import('@/lib/idol/design-review/cw-runtime/cherrybullet-host.mjs').then(async runtime=>{
      if(controller.signal.aborted||!host.current)return;
      mounted=runtime.createCherrybulletReview({host:host.current,catalog,resolveImage,production,onStatus:text=>{if(!controller.signal.aborted)setMessage(text);}});
      const result=await mounted.ready as {status?:string};if(!controller.signal.aborted&&result?.status==='error')setFailed(true);
    }).catch(()=>{if(!controller.signal.aborted){mounted?.destroy();setFailed(true);setMessage('Cherry Bullet 页面暂未载入，可重新读取。');}});
    return()=>{controller.abort();mounted?.destroy();};
  },[attempt,resolveImage,catalog]);
  return <div data-sol15-review-host="cherrybullet">
    <div role="status" aria-live="polite" style={{padding:'12px 20px',font:'14px/1.6 Arial,sans-serif'}}>{message}{failed&&<> <button type="button" onClick={()=>{setFailed(false);setMessage('正在重新读取…');setAttempt(value=>value+1);}}>重新读取</button></>}</div>
    <div ref={host}/>
  </div>;
}

